package owl.nh;
import java.util.*;
import java.nio.file.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
public final class SlayerTests {
 static void check(boolean yes,String why){CoreTests.check(yes,"Slayer: "+why);}
 public static void main(String[] args)throws Exception{
  SlayerCounter c=new SlayerCounter();Object one=new Object(),two=new Object();c.start(10,2);check(!c.died(one,10)&&c.kills==0,"unengaged NPC deaths do not count");c.attack(one,11);check(!c.died(one,11),"other NPC types never count");c.attack(one,10);check(c.died(one,10)&&!c.died(one,10)&&c.kills==1,"one observed attacked NPC death counts once");c.attack(two,10);c.contested(two);check(!c.died(two,10)&&c.kills==1,"contested kills are not credited");c.spawned(two);c.attack(two,10);check(c.died(two,10)&&!c.running&&c.kills==2,"a fresh life can count and the exact goal stops output");c.start(10,1);c.stop();c.attack(one,10);check(!c.died(one,10),"Stop prevents later death callbacks from counting");
  Path temp=Files.createTempDirectory("slayer-launch-");try{Files.createDirectories(temp.resolve("runtime"));Files.writeString(temp.resolve(SlayerLaunchRequest.FILE),"SLAYER_V1");check(SlayerLaunchRequest.consume(temp)&&!SlayerLaunchRequest.consume(temp),"separate app request is consumed once and cleaned");}finally{Files.deleteIfExists(temp.resolve("runtime"));Files.deleteIfExists(temp);}
  runtimeSelection();System.out.println("Slayer checks passed: exact NPC type, own observed attacks, contested deaths, duplicate/lifetime handling, goal stop, passive selection and separate-app request cleanup. Synthetic only.");
 }
 private static void runtimeSelection()throws Exception{
  Map<String,Object> selfValues=new HashMap<>();selfValues.put("getAnimation",123);Map<String,Object> npcValues=new HashMap<>();npcValues.put("getId",10);npcValues.put("getIndex",7);npcValues.put("getName","Test NPC");NPC npc=fakeNpc(npcValues);selfValues.put("getInteracting",npc);Player self=ChambersTests.fake(Player.class,selfValues);Map<String,Object> values=new HashMap<>();values.put("getLocalPlayer",self);values.put("getGameState",GameState.LOGGED_IN);values.put("getTickCount",10);values.put("getNpcs",Arrays.asList(npc));values.put("getPlayers",Arrays.asList(self));Client client=ChambersTests.fake(Client.class,values);java.lang.reflect.Constructor<net.runelite.client.callback.ClientThread> ctor=net.runelite.client.callback.ClientThread.class.getDeclaredConstructor(Client.class);ctor.setAccessible(true);CombatRuntime r=new CombatRuntime(client,ctor.newInstance(client),new net.runelite.client.eventbus.EventBus(),null);
  try{r.slayer.pick();Map<String,Object> menuValues=new HashMap<>();menuValues.put("getIdentifier",7);menuValues.put("getType",MenuAction.NPC_FIRST_OPTION);MenuOptionClicked click=new MenuOptionClicked(ChambersTests.fake(MenuEntry.class,menuValues));r.slayer.menu(click);check(click.isConsumed()&&!r.slayer.picking&&r.slayer.selected.contains("type 10")&&!r.slayer.running(),"picker consumes NPC click to select without starting combat");r.slayer.animation(self);r.slayer.died(npc);r.slayer.lastKilled();check(r.slayer.selected.contains("Test NPC"),"manual observed attack followed by death supports Use last killed");r.slayer.counter.start(10,1);r.slayer.died(npc);check(r.slayer.counter.kills==0,"unobserved deaths do not count in production hook");r.stop("Test F9 equivalent");check(!r.slayer.running()&&!r.slayer.picking,"shared emergency stop cancels Slayer output and picker");}finally{r.slayer.stop("Test cleanup");r.olm.close();}
 }
 private static NPC fakeNpc(Map<String,Object> values){return (NPC)java.lang.reflect.Proxy.newProxyInstance(NPC.class.getClassLoader(),new Class<?>[]{NPC.class},(proxy,method,args)->{if(method.getName().equals("hasAction"))return true;if(method.getName().equals("equals"))return proxy==args[0];if(method.getName().equals("hashCode"))return System.identityHashCode(proxy);Object value=values.get(method.getName());if(value!=null)return value;Class<?> type=method.getReturnType();if(type==boolean.class)return false;if(type==int.class)return -1;if(type==long.class)return 0L;return null;});}
}

